window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#14"]=[{"v":1,"t":"În cartea precedentă am discutat acele subiecte din istoria bisericească pe care era necesar să le tratăm ca introducere și le-am însoțit cu scurte dovezi. Astfel au fost dumnezeirea Cuvântului mântuitor și vechimea învățăturilor pe care le propovăduim, precum și a acelei vieți evanghelice care este trăită de creștini, împreună cu întâmplările care au avut loc în legătură cu recenta arătare a lui Hristos și în legătură cu patima Lui și cu alegerea apostolilor."},{"v":2,"t":"În cartea de față să cercetăm întâmplările care au avut loc după înălțarea Lui, întărind pe unele dintre ele din Scripturile dumnezeiești, iar pe altele din acele scrieri la care ne vom referi din când în când."}];
window.LIB_LAZY["eusebiu-istoria#15"]=[{"v":1,"t":"Întâi, deci, în locul lui Iuda, vânzătorul, a fost ales la apostolat Matia, care, după cum s-a arătat, era și el unul dintre cei Șaptezeci. Și au fost rânduiți la diaconie, pentru slujba adunării, prin rugăciune și punerea mâinilor apostolilor, oameni încercați, la număr de șapte, dintre care unul era Ștefan. El a fost primul, după Domnul, care a fost omorât cu pietre la vremea rânduirii lui de către ucigașii Domnului, ca și cum ar fi fost înălțat chiar în acest scop. Și astfel a fost cel dintâi care a primit cununa, potrivită cu numele lui, ce aparține martirilor lui Hristos, vrednici de răsplata biruinței."},{"v":2,"t":"Apoi Iacov, pe care cei din vechime l-au poreclit Cel Drept din pricina alesei lui virtuți, se însemnează că a fost cel dintâi făcut episcop al Bisericii din Ierusalim. Acest Iacov a fost numit fratele Domnului pentru că era cunoscut ca fiu al lui Iosif, iar Iosif era socotit tatăl lui Hristos, pentru că Fecioara, fiind logodită cu el, „s-a aflat având în pântece de la Duhul Sfânt, înainte de a se fi împreunat ei” (Matei 1:18), după cum arată povestirea sfintelor Evanghelii."},{"v":3,"t":"Dar Clement, în cartea a șasea a Hipotipozelor sale, scrie astfel: „Căci spun că Petru, Iacov și Ioan, după înălțarea Mântuitorului nostru, ca unii care erau și preferați de Domnul nostru, nu au râvnit după cinste, ci l-au ales episcop al Ierusalimului pe Iacov Cel Drept.”"},{"v":4,"t":"Dar același scriitor, în cartea a șaptea a aceleiași lucrări, povestește și următoarele despre el: „Domnul, după învierea Sa, a dat cunoștința lui Iacov Cel Drept și lui Ioan și lui Petru, și ei au dat-o celorlalți apostoli, și ceilalți apostoli celor șaptezeci, dintre care Barnaba era unul. Dar au fost doi Iacovi: unul numit Cel Drept, care a fost aruncat de pe acoperișul templului și a fost bătut până la moarte cu o măciucă de un pivar, și altul care a fost decapitat.” Pavel pomenește și el pe același Iacov Cel Drept, unde scrie: „Pe altul dintre apostoli nu l-am văzut, afară de Iacov, fratele Domnului.” (Galateni 1:19)"},{"v":5,"t":"În acel timp s-a împlinit și făgăduința Mântuitorului nostru către regele osroenilor. Căci Toma, din îndemn dumnezeiesc, a trimis pe Tadeu la Edesa ca predicator și evanghelist al religiei lui Hristos, după cum am arătat puțin mai sus din documentul găsit acolo."},{"v":7,"t":"Când a ajuns în acel loc, a vindecat pe Abgar prin cuvântul lui Hristos; și după ce a adus pe tot poporul de acolo la dispoziția cuvenită a minții prin lucrările lui și l-a dus să se închine puterii lui Hristos, l-a făcut ucenic al învățăturii Mântuitorului. Și din acel timp până în prezent, toată cetatea edesenilor a rămas închinată numelui lui Hristos, dând o dovadă neobișnuită a binefacerii Mântuitorului nostru și față de ei."},{"v":8,"t":"Aceste lucruri au fost scoase din povestiri vechi; dar să ne întoarcem acum din nou la Scriptura dumnezeiască. Când prima și cea mai mare prigoană a fost stârnită de iudei împotriva Bisericii din Ierusalim, în legătură cu martiriul lui Ștefan, și când toți ucenicii, afară de cei doisprezece, au fost risipiți prin Iudeea și Samaria, unii, după cum spune Scriptura dumnezeiască, au mers până în Fenicia, Cipru și Antiohia, dar nu cutezau încă să împărtășească neamurilor cuvântul credinței și de aceea l-au predicat numai iudeilor."},{"v":9,"t":"În acest timp Pavel prigonea încă Biserica și, intrând în casele credincioșilor, târa bărbați și femei și îi dădea la temniță."},{"v":10,"t":"Filip, de asemenea, unul dintre cei care împreună cu Ștefan fuseseră încredințați cu diaconia, fiind printre cei care au fost risipiți, a coborât în Samaria și, fiind plin de puterea dumnezeiască, a predicat întâi cuvântul locuitorilor acelei țări. Și harul dumnezeiesc a lucrat atât de puternic cu el încât chiar Simon Magul, cu mulți alții, a fost atras de cuvintele lui."},{"v":11,"t":"Simon era în acel timp atât de vestit și căpătase, prin scamatoriile lui, o asemenea înrâurire asupra celor amăgiți de el încât era socotit Puterea cea Mare a lui Dumnezeu. Dar în acel timp, uimit de faptele minunate săvârșite de Filip prin puterea dumnezeiască, s-a prefăcut și a falsificat credința în Hristos, mergând până acolo încât a primit botezul."},{"v":12,"t":"Și, lucru de mirare, același lucru se face până în ziua de azi de cei care urmează eresul lui cel mai necurat. Căci ei, după chipul străbunului lor, strecurându-se în Biserică, ca o boală ciumată și leproasă chinuiesc mult pe cei în care pot turna otrava mortală și cumplită ascunsă în ei înșiși. Cei mai mulți dintre aceștia au fost izgoniți îndată ce au fost prinși în răutatea lor, după cum Simon însuși, când a fost dat în vileag de Petru, a primit pedeapsa meritată."},{"v":13,"t":"Dar pe măsură ce predica Evangheliei Mântuitorului înainta zilnic, o anume purtare de grijă a adus din țara etiopienilor un dregător al reginei acelei țări, căci Etiopia este cârmuită și până în ziua de azi, după un obicei strămoșesc, de o femeie. El, cel dintâi dintre neamuri, a primit de la Filip, în urma unei descoperiri, tainele cuvântului dumnezeiesc și, devenind pârga credincioșilor din toată lumea, se spune că a fost cel dintâi care, întorcându-se în țara lui, a vestit cunoașterea Dumnezeului universului și viața-dătătoarea petrecere a Mântuitorului nostru între oameni; astfel că prin el, în adevăr, și-a găsit împlinirea proorocia care spune că „Etiopia își întinde mâna către Dumnezeu”."},{"v":14,"t":"Pe lângă aceștia, Pavel, acel „vas ales” (Fapte 9:15), „nu de la oameni, nici prin om, ci prin descoperirea lui Isus Hristos însuși și a lui Dumnezeu Tatăl, care L-a înviat din morți” (Galateni 1:1), a fost rânduit apostol, fiind învrednicit de chemare printr-o vedenie și printr-un glas care s-a auzit într-o descoperire din cer."}];
window.LIB_LAZY["eusebiu-istoria#16"]=[{"v":1,"t":"Și când minunata înviere și înălțare a Mântuitorului nostru erau deja vestite în lume, după un vechi obicei care stăpânea între cârmuitorii provinciilor, de a raporta împăratului întâmplările noi care aveau loc în ele, ca nimic să nu-i scape, Pontiu Pilat a înștiințat pe Tiberiu despre vestile care se răspândiseră prin toată Palestina cu privire la învierea din morți a Mântuitorului nostru Isus."},{"v":2,"t":"A dat și o povestire despre alte minuni pe care le aflase despre El și cum, după moartea Lui, înviind din morți, era acum crezut de mulți a fi un Dumnezeu. Se spune că Tiberiu a înaintat chestiunea Senatului, dar că aceștia au respins-o, în aparență pentru că nu cercetaseră mai întâi lucrul (căci stăpânea o veche lege că nimeni să nu fie făcut Dumnezeu de romani decât prin votul și decretul Senatului), dar în realitate pentru că învățătura mântuitoare a Evangheliei dumnezeiești nu avea nevoie de întărirea și recomandarea oamenilor."},{"v":3,"t":"Dar deși Senatul romanilor a respins propunerea făcută cu privire la Mântuitorul nostru, Tiberiu a păstrat totuși părerea pe care o avusese la început și nu a născocit nicio măsură dușmănoasă împotriva lui Hristos."},{"v":4,"t":"Aceste lucruri sunt însemnate de Tertulian, un om foarte priceput în legile romanilor și, în alte privințe, de mare reputație și unul dintre cei deosebit de vestiți la Roma. În apărarea lui pentru creștini, care a fost scrisă de el în limba latină și a fost tradusă în greacă, scrie astfel:"},{"v":5,"t":"Dar ca să dăm o povestire a acestor legi de la obârșia lor, era un vechi decret că nimeni nu trebuia consacrat Dumnezeu de împărat până ce Senatul nu și-a exprimat încuviințarea. Marcus Aurelius a făcut astfel cu privire la un anume idol, Alburn. Și acesta este un punct în favoarea învățăturii noastre, că la voi demnitatea dumnezeiască se conferă prin decret omenesc. Dacă un Dumnezeu nu place unui om, nu este făcut Dumnezeu. Astfel, după acest obicei, este necesar ca omul să fie binevoitor față de Dumnezeu."},{"v":6,"t":"Tiberiu, deci, sub care numele lui Hristos și-a făcut intrarea în lume, când această învățătură i-a fost raportată din Palestina, unde începuse întâi, a comunicat cu Senatul, făcându-le limpede că era mulțumit de învățătură. Dar Senatul, de vreme ce nu cercetase el însuși lucrul, l-a respins. Dar Tiberiu a continuat să țină părerea lui proprie și a amenințat cu moartea pe învinuitorii creștinilor. Purtarea de grijă cerească îi insuflase aceasta cu înțelepciune în minte, ca învățătura Evangheliei, nestânjenită la începutul ei, să se răspândească în toate părțile în toată lumea."}];
window.LIB_LAZY["eusebiu-istoria#17"]=[{"v":1,"t":"Astfel, sub înrâurirea puterii cerești și cu împreună-lucrarea dumnezeiască, învățătura Mântuitorului, ca razele soarelui, a luminat curând toată lumea; și îndată, potrivit Scripturilor dumnezeiești, glasul evangheliștilor și apostolilor insuflați a ieșit prin tot pământul și cuvintele lor până la marginea lumii."},{"v":2,"t":"În fiecare cetate și sat s-au întemeiat curând biserici, pline de mulțimi de oameni ca o arie bine umplută. Și cei ale căror minți, din pricina rătăcirilor coborâte la ei de la strămoșii lor, erau legate de vechea boală a superstiției idolatre, au fost, prin puterea lui Hristos lucrând prin învățătura și lucrările minunate ale ucenicilor Lui, eliberați, ca să zic așa, de stăpâni cumpliți și au găsit o slobozire din cea mai crudă robie. S-au lepădat cu scârbă de orice fel de politeism demonic și au mărturisit că nu este decât un singur Dumnezeu, creatorul tuturor lucrurilor, și pe El Îl cinsteau cu riturile adevăratei evlavii, prin închinarea insuflată și rațională pe care Mântuitorul nostru a sădit-o între oameni."},{"v":3,"t":"Dar harul dumnezeiesc fiind acum revărsat peste restul neamurilor, Corneliu din Cezareea Palestinei, cu toată casa lui, printr-o descoperire dumnezeiască și prin lucrarea lui Petru, a primit cel dintâi credința în Hristos; și după el, o mulțime de alți greci din Antiohia, cărora cei risipiți prin prigoana lui Ștefan le propovăduiseră Evanghelia. Când Biserica din Antiohia creștea acum și sporea, și o mulțime de proroci din Ierusalim erau de față, printre ei Barnaba și Pavel și pe lângă ei mulți alți frați, numele de creștini a izvorât acolo întâi, ca dintr-un izvor proaspăt și dătător de viață."},{"v":4,"t":"Și Agab, unul dintre proorocii care erau cu ei, a rostit o proorocie despre foametea care avea să vină, și Pavel și Barnaba au fost trimiși să ușureze nevoile fraților."}];
window.LIB_LAZY["eusebiu-istoria#18"]=[{"v":1,"t":"Tiberiu a murit, după ce domnise vreo douăzeci și doi de ani, și Caiu i-a urmat la imperiu. El a dat îndată cârmuirea iudeilor lui Agrippa, făcându-l rege peste tetrarhiile lui Filip și ale lui Lisania; pe lângă care i-a dat, nu mult după aceea, tetrarhia lui Irod, pedepsind pe Irod (cel sub care a pătimit Mântuitorul) și pe nevasta lui Irodiada cu surghiun veșnic din pricina numeroaselor crime. Josephus este martor al acestor fapte."},{"v":2,"t":"Sub acest împărat a devenit cunoscut Filon, un om foarte vestit nu numai între mulți dintre ai noștri, ci și între mulți învățați din afara Bisericii. Era evreu de neam, dar nu era mai prejos decât niciunul dintre cei care aveau mari demnități în Alexandria. Cât de mult s-a ostenit în Scripturi și în studiile neamului său este limpede tuturor din lucrarea pe care a lăsat-o. Cât de familiar era cu filozofia și cu studiile liberale ale neamurilor străine nu este nevoie să spunem, de vreme ce se povestește că i-a întrecut pe toți contemporanii lui în studiul filozofiei platonice și pitagoreice, căreia i-a dat în chip deosebit luarea lui aminte."}];
window.LIB_LAZY["eusebiu-istoria#19"]=[{"v":1,"t":"Filon ne-a dat, în cinci cărți, o povestire despre nenorocirile iudeilor sub Caiu. Povestește în același timp nebunia lui Caiu: cum se numea pe sine dumnezeu și săvârșea ca împărat nenumărate fapte de tiranie; și descrie mai departe nenorocirile iudeilor sub el și dă o relatare a soliei în care a fost trimis el însuși la Roma în folosul compatrioților lui din Alexandria; cum, când s-a înfățișat înaintea lui Caiu în folosul legilor părinților lui, nu a primit decât râs și batjocură și aproape și-a primejduit viața."},{"v":2,"t":"Josephus pomenește și el aceste lucruri în cartea a optsprezecea a Antichităților sale, în următoarele cuvinte: Ridicându-se o răzvrătire la Alexandria între iudeii care locuiesc acolo și greci, au fost alese trei delegații din fiecare facțiune, care au mers la Caiu."},{"v":3,"t":"Unul dintre delegații alexandrinilor a fost Apion, care a rostit multe clevetiri împotriva iudeilor; spunând, printre altele, că ei neglijau cinstirile datorate lui Cezar. Căci în timp ce toți ceilalți supuși ai Romei ridicau altare și temple lui Caiu și în toate celelalte privințe îl tratau tocmai cum îi tratau pe zei, ei singuri socoteau o rușine să-l cinstească cu statui și să jure pe numele lui."},{"v":4,"t":"Și când Apion a rostit multe învinuiri aspre, prin care nădăjduia să-l stârnească pe Caiu, cum era și probabil, Filon, căpetenia soliei iudeilor, un om vestit în toate privințele, fratele lui Alexandru Alabarhul și nu nepriceput în filozofie, era pregătit să înceapă o apărare ca răspuns la învinuirile lui."},{"v":5,"t":"Dar Caiu l-a prevenit și i-a poruncit să plece și, fiind foarte mâniat, era vădit că plănuia vreo măsură aspră împotriva lor. Și Filon a plecat acoperit de ocări și a spus iudeilor care erau cu el să aibă curaj; căci, în timp ce Caiu se înfuria împotriva lor, el se lupta deja, în fapt, cu Dumnezeu."},{"v":6,"t":"Până aici Josephus. Și Filon însuși, în lucrarea Despre solie pe care a scris-o, descrie exact și amănunțit lucrurile care au fost făcute de el în acel timp. Dar eu voi omite cea mai mare parte dintre ele și voi însemna numai acele lucruri care vor face limpede cititorului că nenorocirile iudeilor au venit peste ei nu mult după faptele lor îndrăznețe împotriva lui Hristos și din pricina lor."},{"v":7,"t":"Și, în primul rând, povestește că la Roma, în domnia lui Tiberiu, Sejan, care se bucura în acel timp de mare înrâurire pe lângă împărat, a făcut toate silințele să nimicească desăvârșit neamul iudeu; și că în Iudeea, Pilat, sub care s-au săvârșit crimele împotriva Mântuitorului, a încercat ceva împotriva legii iudeilor în privința templului, care stătea pe atunci încă în picioare la Ierusalim, și i-a stârnit la cele mai mari tulburări."}];
window.LIB_LAZY["eusebiu-istoria#20"]=[{"v":1,"t":"După moartea lui Tiberiu, Caiu a primit imperiul și, pe lângă nenumărate alte fapte de tiranie împotriva multor popoare, a chinuit mult în chip deosebit tot neamul iudeilor. Aceste lucruri le putem afla pe scurt din cuvintele lui Filon, care scrie astfel:"},{"v":2,"t":"„Atât de mare era toana lui Caiu în purtarea lui față de toți și mai ales față de neamul iudeilor. Pe aceștia îi ura atât de amarnic încât și-a însușit locurile lor de închinare din celelalte cetăți și, începând cu Alexandria, le-a umplut cu chipuri și statui ale lui însuși (căci îngăduind altora să le ridice, în realitate le ridica el însuși). Templul din cetatea sfântă, care rămăsese până atunci neatins și fusese privit ca un adăpost inviolabil, l-a schimbat și l-a prefăcut într-un templu al lui, ca să se numească templul lui Jupiter cel văzut, Caiu cel tânăr.”"},{"v":3,"t":"Nenumărate alte nenorociri cumplite și aproape de nedescris, care au căzut peste iudeii din Alexandria în timpul domniei aceluiași împărat, sunt însemnate de același autor într-o a doua lucrare, căreia i-a dat titlul Despre virtuți. Cu el se învoiește și Josephus, care arată și el că nenorocirile întregului neam au început cu vremea lui Pilat și cu crimele lor îndrăznețe împotriva Mântuitorului."},{"v":4,"t":"Auzi ce spune în cartea a doua a Războiului său iudaic, unde scrie astfel: „Pilat, fiind trimis în Iudeea ca procurator de Tiberiu, a dus în taină la Ierusalim, noaptea, chipuri acoperite ale împăratului, numite stindarde. A doua zi aceasta a pricinuit cea mai mare tulburare între iudei. Căci cei care erau aproape s-au încurcat la vederea lor, văzându-și legile, ca să zicem așa, călcate în picioare. Căci ei nu îngăduie să se așeze niciun chip în cetatea lor.”"},{"v":5,"t":"Punând aceste lucruri alături de scrierile evangheliștilor, vei vedea că n-a trecut mult până a venit peste ei pedeapsa pentru strigătul pe care l-au scos sub același Pilat, când au strigat că nu au alt rege decât pe Cezar. (Ioan 19:15)"},{"v":6,"t":"Același scriitor povestește mai departe că după aceasta i-a ajuns o altă nenorocire. Scrie astfel: După aceasta a stârnit o altă tulburare, folosind vistieria sfântă, care se numește Corban, la facerea unui apeduct lung de trei sute de stadii."},{"v":7,"t":"Mulțimea a fost foarte nemulțumită de aceasta și, când Pilat era la Ierusalim, au înconjurat tribunalul lui și au făcut plângeri tari. Dar el, prevenind tulburarea, împrăștiase printre mulțime ostași înarmați deghizați în haine de cetățeni, oprindu-le să se slujească de sabie, dar poruncindu-le să lovească cu bâte pe cei care vor striga. Acestora le-a dat acum semnul stabilit mai dinainte de pe tribunal. Și iudeii fiind loviți, mulți dintre ei au pierit din pricina loviturilor, iar mulți alții au fost călcați în picioare de propriii lor compatrioți în fuga lor și și-au pierdut astfel viețile. Dar mulțimea, înfricoșată de soarta celor omorâți, a tăcut."},{"v":8,"t":"Pe lângă acestea, același autor însemnează multe alte tulburări care au fost stârnite chiar în Ierusalim și arată că din acel timp răzvrătirile, războaiele și uneltirile vătămătoare s-au urmat unele pe altele în repezi succesiuni și nu au încetat niciodată în cetate și în toată Iudeea până când, în cele din urmă, asediul lui Vespasian i-a copleșit. Astfel răzbunarea dumnezeiască i-a ajuns pe iudei pentru crimele pe care au cutezat să le săvârșească împotriva lui Hristos."}];
window.LIB_LAZY["eusebiu-istoria#21"]=[{"v":1,"t":"Este vrednic de remarcat că însuși Pilat, care a fost guvernator pe vremea Mântuitorului nostru, se povestește că a căzut în asemenea nenorociri sub Caiu, ale cărui vremuri le însemnăm, încât a fost silit să-și fie propriul ucigaș și călău; și astfel răzbunarea dumnezeiască, după cum se pare, nu a zăbovit să-l ajungă. Aceasta o spun acei istorici greci care au însemnat olimpiadele, împreună cu întâmplările respective care au avut loc în fiecare perioadă."}];
window.LIB_LAZY["eusebiu-istoria#22"]=[{"v":1,"t":"Caiu ținuse puterea nu cu totul patru ani, când i-a urmat împăratul Claudiu. Sub el lumea a fost cercetată de o foamete, pe care scriitori cu totul străini de religia noastră au însemnat-o în istoriile lor. Și astfel prezicerea lui Agab, însemnată în Faptele Apostolilor (Fapte 11:28), potrivit căreia toată lumea avea să fie cercetată de o foamete, și-a primit împlinirea."},{"v":2,"t":"Și Luca, în Fapte, după ce pomenește foametea din vremea lui Claudiu și spune că frații din Antiohia, fiecare după puterea lui, au trimis frații din Iudeea prin mâinile lui Pavel și Barnaba (Fapte 11:29-30), adaugă următoarea povestire."}];
window.LIB_LAZY["eusebiu-istoria#23"]=[{"v":1,"t":"„Și în acel timp (Fapte 12:1-2)” (este limpede că se referă la vremea lui Claudiu) „regele Irod și-a întins mâinile ca să chinuiască pe unii din Biserică. Și a omorât cu sabia pe Iacov, fratele lui Ioan.”"},{"v":2,"t":"Și despre acest Iacov, Clement, în cartea a șaptea a Hipotipozelor sale, povestește o istorisire vrednică de pomenire; spunând-o după cum a primit-o de la cei care au trăit înaintea lui. El spune că cel care l-a dus pe Iacov la scaunul de judecată, când l-a văzut mărturisind, a fost mișcat și a mărturisit că și el era creștin."},{"v":3,"t":"Amândoi au fost, deci, duși împreună, spune el; și pe drum a rugat pe Iacov să-l ierte. Iar el, după ce s-a gândit puțin, a zis: „Pacea să fie cu tine”, și l-a sărutat. Și astfel amândoi au fost decapitați în același timp."},{"v":4,"t":"Și apoi, după cum spune Scriptura dumnezeiască (Fapte 12:3 urm.), Irod, la moartea lui Iacov, văzând că fapta plăcuse iudeilor, s-a năpustit și asupra lui Petru și l-a dat la temniță și l-ar fi omorât dacă nu ar fi fost, prin arătarea dumnezeiască a unui înger care a venit la el noaptea, eliberat în chip minunat din lanțurile lui și astfel slobozit pentru slujba Evangheliei. Așa a fost purtarea de grijă a lui Dumnezeu în privința lui Petru."}];
window.LIB_LAZY["eusebiu-istoria#24"]=[{"v":1,"t":"Urmările întreprinderii regelui împotriva apostolilor nu au zăbovit mult, ci slujitorul răzbunător al dreptății dumnezeiești l-a ajuns îndată după uneltirile lui împotriva lor, după cum însemnează Cartea Faptelor. Căci, când a călătorit la Cezareea, într-o zi de sărbătoare de seamă, îmbrăcat într-un veșmânt strălucitor și împărătesc, a ținut o cuvântare poporului de pe un scaun înalt înaintea tribunalului. Și când toată mulțimea a aplaudat cuvântarea, ca și cum ar fi fost glasul unui dumnezeu și nu al unui om, Scriptura povestește că un înger al Domnului l-a lovit și, fiind mâncat de viermi, și-a dat duhul. (Fapte 12:23)"},{"v":2,"t":"Trebuie să admirăm povestirea lui Josephus pentru învoirea ei cu Scripturile dumnezeiești în privința acestei întâmplări minunate; căci mărturisește limpede adevărul în cartea a nouăsprezecea a Antichităților sale, unde povestește minunea în următoarele cuvinte:"},{"v":3,"t":"Împlinise al treilea an al domniei lui peste toată Iudeea când a venit la Cezareea, care se numea mai înainte Turnul lui Straton. Acolo a dat jocuri în cinstea lui Cezar, aflând că aceasta era o sărbătoare ținută pentru siguranța lui Cezar. La această sărbătoare s-a adunat o mare mulțime dintre cei mai de seamă și mai cinstiți oameni din provincie."},{"v":4,"t":"Și în a doua zi a jocurilor a mers la teatru în revărsatul zorilor, purtând un veșmânt cu totul de argint și de o țesătură minunată. Și acolo argintul, luminat de reflexia primelor raze ale soarelui, strălucea minunat, scânteind atât de tare încât pricinuia un fel de teamă și groază celor care se uitau la el."},{"v":5,"t":"Și îndată lingușitorii lui, unii dintr-un loc, alții din altul, și-au ridicat glasurile într-un chip care nu era spre binele lui, numindu-l dumnezeu și zicând: „Fii milostiv; dacă până acum ne-am temut de tine ca de un om, de acum înainte mărturisim că ești mai presus de firea muritorilor.”"},{"v":6,"t":"Regele nu i-a mustrat și nici nu a respins lingușirea lor nelegiuită. Dar după puțin, uitându-se în sus, a văzut un înger stând deasupra capului său. Și a priceput îndată că acesta va fi pricina de rău, după cum fusese odinioară pricina de noroc bun, și a fost lovit de o durere care îi străpungea inima."},{"v":7,"t":"Și îndată o strâmtorare, începând cu cea mai mare violență, i-a cuprins măruntaiele. Și, uitându-se la prietenii lui, a zis: „Eu, dumnezeul vostru, sunt acum poruncit să părăsesc această viață; și soarta respinge astfel pe loc cuvintele mincinoase pe care tocmai le-ați rostit despre mine. Cel care a fost numit nemuritor de voi este acum dus la moarte; dar destinul nostru trebuie primit cum l-a hotărât Dumnezeu. Căci ne-am petrecut viața nicidecum fără slavă, ci în acea strălucire care se numește fericire.”"},{"v":8,"t":"Și când a spus aceasta, s-a chinuit cu o sporire a durerii. A fost dus, deci, în grabă la palat, în timp ce vestea s-a răspândit între toți că regele va muri negreșit în curând. Dar mulțimea, cu nevestele și copiii, șezând pe sac după obiceiul părinților lor, se ruga lui Dumnezeu pentru rege și toate locurile erau pline de tânguire și lacrimi. Și regele, pe când zăcea într-o cameră înaltă și îi vedea jos culcați la pământ, nu s-a putut opri să plângă și el."},{"v":9,"t":"Și după ce a suferit neîncetat cinci zile cu dureri de măruntaie, a părăsit această viață, în al cincizeci și patrulea an al vârstei lui și în al șaptelea an al domniei lui. Patru ani a domnit sub împăratul Caiu — trei dintre ei peste tetrarhia lui Filip, la care i s-a adăugat în al patrulea an cea a lui Irod — și trei ani în timpul domniei împăratului Claudiu."},{"v":10,"t":"Mă minunez foarte mult că Josephus, în aceste lucruri ca și în altele, se învoiește atât de deplin cu Scripturile dumnezeiești. Dar dacă i s-ar părea cuiva că este o nepotrivire în privința numelui regelui, timpul cel puțin și întâmplările arată că se are în vedere aceeași persoană, fie că schimbarea numelui a fost pricinuită de greșeala unui copist, fie că se datorează faptului că el, ca atâția, purta două nume."}];
window.LIB_LAZY["eusebiu-istoria#25"]=[{"v":1,"t":"Luca, în Fapte, îl înfățișează pe Gamaliel spunând, la sfatul care s-a ținut despre apostoli, că în timpul la care se referea „s-a ridicat Teuda, lăudându-se că este cineva; care a fost omorât; și toți câți ascultau de el au fost risipiți”. (Fapte 5:36) Să adăugăm, deci, povestirea lui Josephus despre acest om. El însemnează în lucrarea pomenită chiar mai sus următoarele împrejurări:"},{"v":2,"t":"Pe când Fad era procuratorul Iudeii, un anume înșelător numit Teuda a convins o foarte mare mulțime să-și ia averile și să-l urmeze la râul Iordan. Căci spunea că este prooroc și că râul se va despărți la porunca lui și le va da o trecere ușoară."},{"v":3,"t":"Și cu aceste cuvinte a amăgit pe mulți. Dar Fad nu i-a lăsat să se bucure de nebunia lor, ci a trimis împotriva lor o ceată de călăreți, care au căzut asupra lor pe neașteptate și au omorât pe mulți dintre ei și au luat pe mulți alții vii, în timp ce pe Teuda însuși l-au prins, i-au tăiat capul și l-au dus la Ierusalim. Pe lângă aceasta, pomenește și foametea care a avut loc în domnia lui Claudiu, în cuvintele următoare."}];
window.LIB_LAZY["eusebiu-istoria#26"]=[{"v":1,"t":"„Și în acel timp s-a întâmplat că a venit marea foamete în Iudeea, în care regina Elena, cumpărând grâu din Egipt cu mari sume, l-a împărțit celor lipsiți.”"},{"v":2,"t":"Vei găsi că această spusă se învoiește și cu Faptele Apostolilor, unde se spune că ucenicii din Antiohia, „fiecare după puterea lui, au hotărât să trimită ajutor fraților care locuiau în Iudeea; ceea ce au și făcut, trimițându-l bătrânilor prin mâinile lui Barnaba și Pavel”."},{"v":3,"t":"Dar monumente strălucitoare ale acestei Elene, pe care a pomenit-o istoricul, se mai arată în suburbiile cetății care se numește acum Elia. Dar se spune că a fost regină a adiabenilor."}];
window.LIB_LAZY["eusebiu-istoria#27"]=[{"v":1,"t":"Dar credința în Mântuitorul și Domnul nostru Isus Hristos fiind acum răspândită între toți oamenii, dușmanul mântuirii omului a născocit un plan ca să pună stăpânire pe cetatea împărătească. A dus acolo pe pomenitul Simon, l-a ajutat în meșteșugurile lui înșelătoare, a rătăcit pe mulți dintre locuitorii Romei și i-a adus astfel în propria lui putere."},{"v":2,"t":"Aceasta o spune Iustin, unul dintre scriitorii noștri de seamă care a trăit nu mult după vremea apostolilor. Despre el voi vorbi la locul potrivit. Ia și citește lucrarea acestui om, care în prima Apologie pe care a adresat-o lui Antonin în folosul religiei noastre scrie astfel:"},{"v":3,"t":"Și după înălțarea Domnului la cer, demonii au scos înainte pe unii oameni care spuneau că sunt dumnezei și care nu numai că au fost lăsați de voi să meargă neprigoniți, ci au fost socotiți vrednici și de cinstiri. Unul dintre ei era Simon, un samaritean din satul Gitto, care în domnia lui Claudiu Cezar a săvârșit în cetatea voastră împărătească niște mari fapte de magie prin meșteșugul demonilor care lucrau în el și a fost socotit dumnezeu și, ca dumnezeu, a fost cinstit de voi cu o statuie, care a fost ridicată pe râul Tibru, între cele două poduri, și purta această inscripție în limba latină: Simoni Deo Sancto, adică Lui Simon, Dumnezeul cel Sfânt."},{"v":4,"t":"Și aproape toți samaritenii și câțiva chiar din alte neamuri îl mărturisesc și i se închină ca celui dintâi Dumnezeu. Și umbla cu el în acel timp o anume Elena, care fusese mai înainte o desfrânată în Tirul Feniciei; și pe ea o numesc prima idee care a ieșit din el."},{"v":5,"t":"Iustin povestește aceste lucruri și Irineu se învoiește cu el în cartea întâi a lucrării sale Împotriva ereziilor, unde dă o povestire despre om și despre învățătura lui nesfințită și necurată. Ar fi de prisos să citez aici povestirea lui, căci este cu putință celor care vor să cunoască obârșia, viețile și învățăturile mincinoase ale fiecărui eresiarh care l-a urmat, precum și obiceiurile practicate de ei toți, să le găsească tratate pe larg în lucrarea pomenită a lui Irineu."},{"v":6,"t":"Am înțeles că Simon a fost autorul tuturor ereziilor. Din vremea lui până în prezent, cei care i-au urmat eresul au prefăcut filozofia cumpătată a creștinilor, care este vestită între toți din pricina curăției vieții. Dar totuși au îmbrățișat din nou superstițiile idolilor, de care păreau că s-au lepădat; și cad cu fața la pământ înaintea chipurilor și icoanelor lui Simon însuși și ale pomenitei Elena care era cu el; și cutează să li se închine cu tămâie, jertfe și libații."},{"v":7,"t":"Dar acele lucruri pe care le țin mai tainice decât acestea, despre care spun că cineva, la prima lor auzire, s-ar uimi și, ca să folosim una dintre expresiile scrise la modă între ei, s-ar încurca, sunt în adevăr pline de lucruri uluitoare, de nebunie și prostie, fiind de asemenea fel încât este cu neputință nu numai să fie date în scris, ci și ca oamenii cuviincioși să le rostească măcar cu buzele din pricina excesivei lor josnicii și desfrânări."},{"v":8,"t":"Căci tot ce se putea închipui, mai ticălos decât cel mai ticălos lucru — toate acestea au fost întrecute de această sectă preaurâtă, alcătuită din cei care își fac joc de acele nenorocite femei care sunt, în sens propriu, copleșite de tot felul de vicii."}];
window.LIB_LAZY["eusebiu-istoria#28"]=[{"v":1,"t":"Puterea cea rea, care urăște tot ce este bun și uneltește împotriva mântuirii oamenilor, l-a rânduit în acel timp pe Simon părinte și autor al unei asemenea răutăți, ca și cum ar fi vrut să facă din el un mare potrivnic al marilor apostoli insuflați ai Mântuitorului nostru."},{"v":2,"t":"Căci acel har dumnezeiesc și ceresc, care lucrează împreună cu slujitorii lui, prin arătarea și prezența lor, a stins curând flacăra aprinsă a răului și a smerit și a doborât prin ei „orice înălțime care se ridică împotriva cunoașterii lui Dumnezeu”. (2 Corinteni 10:5)"},{"v":3,"t":"De aceea nici uneltirea lui Simon, nici a altora care s-au ridicat în acea epocă nu au putut izbuti nimic în acele vremuri apostolice. Căci totul era biruit și supus de strălucirile adevărului și de însuși cuvântul dumnezeiesc, care tocmai începuse să lumineze din cer peste oameni și care înflorea atunci pe pământ și locuia în apostolii înșiși."},{"v":4,"t":"Îndată pomenitul înșelător a fost lovit în ochii minții lui de o scânteiere dumnezeiască și minunată și, după ce faptele rele făcute de el au fost dovedite întâi de apostolul Petru în Iudeea, a fugit și a făcut o mare călătorie peste mare de la răsărit la apus, socotind că numai astfel ar putea trăi după mintea lui."},{"v":5,"t":"Și, venind în cetatea Romei, cu puternica împreună-lucrare a acelei puteri care stătea acolo la pândă, a izbutit într-un timp scurt atât de bine în întreprinderea lui încât cei care locuiau acolo l-au cinstit ca pe un dumnezeu, ridicându-i o statuie."},{"v":6,"t":"Dar aceasta nu a ținut mult. Căci îndată, în timpul domniei lui Claudiu, purtarea de grijă preabună și plină de har, care veghează peste toate, l-a dus pe Petru, cel mai tare și cel mai mare dintre apostoli și cel care, din pricina virtuții lui, era cel care vorbea în numele tuturor celorlalți, la Roma, împotriva acestui mare stricător al vieții. Îmbrăcat în armură dumnezeiască, ca un nobil comandant al lui Dumnezeu, el a adus scumpa marfă a luminii înțelegerii de la răsărit celor care locuiau la apus, vestind însăși lumina și cuvântul care aduce mântuire sufletelor și predicând împărăția cerurilor."}];
window.LIB_LAZY["eusebiu-istoria#29"]=[{"v":1,"t":"Și astfel, când cuvântul dumnezeiesc și-a făcut sălaș printre ei, puterea lui Simon a fost stinsă și îndată nimicită, împreună cu omul însuși. Și atât de mult a luminat strălucirea evlaviei mințile ascultătorilor lui Petru încât nu se mulțumeau să audă o singură dată și nu erau mulțumiți cu învățătura nescrisă a Evangheliei dumnezeiești, ci cu tot felul de rugăminți l-au rugat pe Marcu, un urmaș al lui Petru și cel a cărui Evanghelie există, să le lase un monument scris al învățăturii care le fusese împărtășită prin viu grai. Nici nu au încetat până ce nu au izbutit cu omul și au devenit astfel pricina Evangheliei scrise care poartă numele lui Marcu."},{"v":2,"t":"Și se spune că Petru — când a aflat, printr-o descoperire a Duhului, ce se făcuse — s-a bucurat de râvna oamenilor și că lucrarea a căpătat încuviințarea autorității lui pentru a fi folosită în biserici. Clement, în cartea a opta a Hipotipozelor sale, dă această povestire și cu el se învoiește episcopul Hierapolei numit Papias. Și Petru pomenește pe Marcu în prima lui epistolă, pe care se spune că a scris-o chiar la Roma, după cum arată el când numește cetatea, în chip de figură, Babilon, ca în cuvintele următoare: „Biserica care este în Babilon, aleasă împreună cu voi, vă salută; și Marcu, fiul meu.” (1 Petru 5:13)"}];
window.LIB_LAZY["eusebiu-istoria#30"]=[{"v":1,"t":"Și se spune că acest Marcu a fost cel dintâi trimis în Egipt și că a vestit Evanghelia pe care o scrisese și a întemeiat întâi biserici la Alexandria."},{"v":2,"t":"Și mulțimea credincioșilor, atât bărbați, cât și femei, care s-au adunat acolo chiar de la început și trăiau o viață de cea mai filozofică și neînfrânată asceză, a fost atât de mare încât Filon a socotit că merită osteneala să descrie îndeletnicirile lor, adunările lor, ospețele lor și tot felul lor de viață."}];
window.LIB_LAZY["eusebiu-istoria#31"]=[{"v":1,"t":"Se mai spune că Filon, în domnia lui Claudiu, l-a cunoscut la Roma pe Petru, care predica atunci acolo. Nici nu este aceasta, într-adevăr, nepotrivită, căci lucrarea despre care am vorbit, și care a fost alcătuită de el câțiva ani mai târziu, cuprinde în chip vădit acele rânduieli ale Bisericii care sunt păzite chiar și până în ziua de azi între noi."},{"v":2,"t":"Și de vreme ce descrie cât se poate de exact viața asceților noștri, este limpede că nu numai că i-a cunoscut, ci i-a și încuviințat, venerând și lăudând pe oamenii apostolici din vremea lui, care erau, se pare, din neamul evreilor și de aceea păzeau, după felul iudeilor, cea mai mare parte din obiceiurile celor din vechime."},{"v":3,"t":"În lucrarea căreia i-a dat titlul Despre viața contemplativă sau despre rugători, după ce afirmă mai întâi că nu va adăuga la cele pe care e gata să le povestească nimic împotriva adevărului sau născocit de el, spune că acești oameni se numeau terapeuți, iar femeile care erau cu ei terapeutride. Adaugă apoi pricinile unui asemenea nume, explicându-l din faptul că aplicau leacuri și vindecau sufletele celor care veneau la ei, ușurându-i, ca niște doctori, de patimile rele, sau din faptul că slujeau și se închinau Dumnezeirii în curăție și sinceritate."},{"v":4,"t":"Dacă Filon însuși le-a dat acest nume, folosind o poreclă potrivită felului lor de viață, sau dacă cei dintâi dintre ei și-au spus într-adevăr așa la început, pentru că numele de creștini nu era încă cunoscut pretutindeni, nu avem nevoie să discutăm aici."},{"v":5,"t":"Mărturisește totuși că mai întâi de toate ei se leapădă de averea lor. Când încep felul filozofic de viață, spune el, își dau bunurile rudelor lor și apoi, lepădându-se de toate grijile vieții, ies dincolo de ziduri și locuiesc în câmpuri și grădini pustii, știind bine că împărtășirea cu oameni de alt fel este nefolositoare și vătămătoare. Aceasta o făceau în acel timp, după cum pare probabil, sub înrâurirea unei credințe înfocate și arzătoare, practicând cu întrecere felul de viață al proorocilor."},{"v":6,"t":"Căci în Faptele Apostolilor, o lucrare recunoscută de toți ca autentică, este însemnat că toți tovarășii apostolilor și-au vândut posesiunile și averile și au împărțit tuturor după nevoia fiecăruia, așa încât nimeni dintre ei nu ducea lipsă. „Căci câți erau stăpâni de ogoare sau case”, după cum spune povestirea, „le vindeau și aduceau prețul celor vândute și îl puneau la picioarele apostolilor, ca să se facă împărțire fiecărui om după cum avea nevoie.” (Fapte 2:45)"},{"v":7,"t":"Filon mărturisește fapte foarte asemănătoare cu cele descrise aici și adaugă apoi următoarea povestire: Pretutindeni în lume se găsește acest neam. Căci se cuvenea ca și grecul, și barbarul să ia parte la ce este desăvârșit de bun. Dar neamul abundă mai ales în Egipt, în fiecare dintre așa-numitele lui nomuri, și mai ales în jurul Alexandriei."},{"v":8,"t":"Cei mai buni oameni din fiecare parte emigrează, ca la o colonie a patriei terapeuților, într-un anume loc foarte potrivit care se află deasupra lacului Maria, pe un deal scund, așezat minunat din pricina siguranței și a blândeții aerului."},{"v":9,"t":"Și apoi, ceva mai departe, după ce descrie felul de case pe care le aveau, spune următoarele despre bisericile lor, care erau risipite încoace și încolo: „În fiecare casă este o încăpere sfântă, care se numește sfânt locaș și mănăstire, unde, cu totul singuri, săvârșesc tainele vieții religioase. Nu aduc nimic în ea, nici băutură, nici mâncare, nici vreunul din celelalte lucruri care contribuie la nevoile trupului, ci numai legile și oracolele insuflate ale proorocilor și imnuri și alte asemenea lucruri care sporesc și desăvârșesc cunoștința și evlavia lor.”"},{"v":10,"t":"Și după alte lucruri, spune: Tot intervalul, de dimineață până seara, este pentru ei un timp de exercițiu. Căci citesc Sfintele Scripturi și explică filozofia părinților lor într-un chip alegoric, socotind cuvintele scrise ca simboluri ale adevărului ascuns, care este împărtășit în figuri întunecoase."},{"v":11,"t":"Au și scrieri ale unor oameni din vechime, care au fost întemeietorii sectei lor și care au lăsat multe monumente ale metodei alegorice. Acestea le folosesc ca modele și imită principiile lor."},{"v":12,"t":"Aceste lucruri par a fi fost spuse de un om care i-a auzit explicându-și scrierile sfinte. Dar este foarte probabil că lucrările celor din vechime, pe care spune că le aveau, erau Evangheliile și scrierile apostolilor și probabil unele tâlcuiri ale proorocilor vechi, cum sunt cele cuprinse în Epistola către Evrei și în multe alte epistole ale lui Pavel."},{"v":13,"t":"Apoi iarăși scrie astfel despre noii psalmi pe care îi compuneau: „Astfel că nu-și petrec timpul numai în meditație, ci compun și cântări și imnuri către Dumnezeu în toată varietatea de metru și melodie, deși le împart, desigur, în măsuri de o solemnitate mai mult decât obișnuită.”"},{"v":14,"t":"Aceeași carte cuprinde o povestire despre multe alte lucruri, dar s-a părut necesar să alegem acele fapte care arată trăsăturile felului bisericesc de viață."},{"v":15,"t":"Dar dacă cineva socotește că ce s-a spus nu este propriu rânduielii evanghelice, ci că poate fi aplicat și altora decât celor pomeniți, să fie convins de cuvintele următoare ale aceluiași autor, în care, dacă este fără părtinire, va găsi o mărturie nezdruncinată în această privință. Cuvintele lui Filon sunt următoarele:"},{"v":16,"t":"Punând cumpătarea ca un fel de temelie în suflet, zidesc pe ea celelalte virtuți. Niciunul dintre ei nu poate lua hrană sau băutură înainte de apusul soarelui, de vreme ce socotesc filozofarea o lucrare vrednică de lumină, iar îngrijirea nevoilor trupului potrivită numai în întuneric, și de aceea rânduiesc ziua celei dintâi, iar celei din urmă o mică parte a nopții."},{"v":17,"t":"Dar unii, în care locuiește o mare dorință de cunoaștere, uită să ia hrană trei zile; și unii se desfată atât de mult și se ospătează atât de bogat cu înțelepciunea, care dă învățături din belșug și fără măsură, încât se înfrânează chiar de două ori pe atât și sunt deprinși, după șase zile, să ia abia hrana necesară. Aceste spuse ale lui Filon le socotim că se referă limpede și fără îndoială la cei din împărtășirea noastră."},{"v":18,"t":"Dar dacă după acestea cineva stăruie încă cu încăpățânare în tăgăduirea trimiterii, să-și lepede neîncrederea și să fie convins de pilde și mai izbitoare, care nu se găsesc nicăieri altundeva decât în religia evanghelică a creștinilor."},{"v":19,"t":"Căci se spune că erau și femei cu cei despre care vorbim și că cele mai multe dintre ele erau fecioare bătrâne care își păstraseră castitatea, nu din nevoie, ca unele dintre preotesele grecilor, ci mai degrabă prin propria lor alegere, din râvnă și dorința de înțelepciune. Și că, în dorința lor înfocată de a trăi cu ea ca tovarășă, nu luau seama la plăcerile trupului, căutând nu urmași muritori, ci nemuritori, pe care numai sufletul evlavios este în stare să-i nască din sine."},{"v":20,"t":"Apoi, după puțin, adaugă și mai apăsat: „Tâlcuiesc Sfintele Scripturi în chip figurat, prin alegorii. Căci întreaga lege pare acestor oameni să semene cu un organism viu, din care cuvintele rostite alcătuiesc trupul, iar înțelesul ascuns, păstrat înăuntrul cuvintelor, alcătuiește sufletul. Acest înțeles ascuns a fost studiat mai întâi deosebit de această sectă, care vede, descoperite ca într-o oglindă a numelor, frumusețile covârșitoare ale gândurilor.”"},{"v":21,"t":"De ce este necesar să adăugăm la acestea adunările lor și îndeletnicirile respective ale bărbaților și ale femeilor în acele adunări și practicile care sunt păzite din obișnuință până în ziua de azi de noi, mai ales cele pe care obișnuim să le păzim la sărbătoarea patimii Mântuitorului, cu post, priveghere de noapte și studiul Cuvântului dumnezeiesc."},{"v":22,"t":"Aceste lucruri le-a povestit autorul pomenit mai sus în lucrarea lui, arătând un fel de viață care a fost păstrat până în timpul de față numai de noi, însemnând mai ales privegherile ținute în legătură cu marea sărbătoare și exercițiile săvârșite în acele privegheri și imnurile rostite de obicei de noi și descriind cum, în timp ce unul cântă regulat în ritm, ceilalți ascultă în tăcere și se unesc în cântare numai la sfârșitul imnurilor; și cum, în zilele pomenite, dorm pe pământ pe paturi de paie și, ca să folosim propriile lui cuvinte, „nu gustă deloc vin, nici carne, ci apa este singura lor băutură, iar tocana cu pâinea lor este sarea și isopul”."},{"v":23,"t":"Pe lângă aceasta, Filon descrie rânduiala demnităților care există între cei care duc slujbele Bisericii, pomenind diaconia și slujba de episcop, care are întâietate peste toate celelalte. Dar oricine dorește o cunoaștere mai exactă a acestor lucruri o poate căpăta din istoria deja citată."},{"v":24,"t":"Dar că Filon, când a scris aceste lucruri, avea în vedere pe cei dintâi vestitori ai Evangheliei și obiceiurile transmise de la început de apostoli, este limpede oricui."}];
window.LIB_LAZY["eusebiu-istoria#32"]=[{"v":1,"t":"Bogat în limbaj, cuprinzător în gândire, sublim și înalt în privințele lui asupra Scripturii dumnezeiești, Filon a alcătuit felurite și variate tâlcuiri ale cărților sfinte. Pe de o parte, expune în ordine întâmplările însemnate în Geneza în cărțile cărora le dă titlul Alegoriile legilor sfinte; pe de altă parte, face împărțiri succesive ale capitolelor din Scripturi care sunt subiectul cercetării și dă obiecții și soluții, în cărțile pe care le numește foarte potrivit Întrebări și răspunsuri la Geneza și Exodul."},{"v":2,"t":"Mai sunt, pe lângă acestea, tratate lucrate de el anume asupra unor subiecte, cum sunt cele două cărți Despre agricultură și tot atâtea Despre beție; și alte câteva deosebite prin titluri diferite, potrivite cuprinsului fiecăreia; de pildă, Despre lucrurile pe care mintea trează le dorește și le urăște, Despre încurcarea limbilor, Despre fugă și descoperire, Despre adunarea pentru învățătură, Despre întrebarea «Cine este moștenitor al lucrurilor dumnezeiești?» sau Despre împărțirea lucrurilor în egale și inegale, și mai departe lucrarea Despre cele trei virtuți care au fost descrise de Moise împreună cu altele."},{"v":3,"t":"Pe lângă acestea este lucrarea Despre cei ale căror nume au fost schimbate și de ce au fost schimbate, în care spune că a scris și două cărți Despre legăminte."},{"v":4,"t":"Și mai este o lucrare a lui Despre emigrare și una Despre viața unui înțelept desăvârșit în dreptate sau Despre legile nescrise; și mai departe lucrarea Despre uriași sau Despre neschimbabilitatea lui Dumnezeu și o carte întâi, a doua, a treia, a patra și a cincea Despre propoziția că visele după Moise sunt trimise de Dumnezeu. Acestea sunt cărțile despre Geneza care au ajuns până la noi."},{"v":5,"t":"Dar despre Exod cunoaștem cartea întâi, a doua, a treia, a patra și a cincea de Întrebări și răspunsuri; precum și pe cea Despre cort și pe cea Despre cele zece porunci și cele patru cărți Despre legile care se referă în chip deosebit la împărțirile principale ale celor zece porunci, și alta Despre animalele menite jertfei și Despre felurile de jertfă, și alta Despre răsplătirile rânduite în lege pentru cei buni și despre pedepsele și blestemele rânduite pentru cei răi."},{"v":6,"t":"Pe lângă toate acestea mai sunt păstrate și unele lucrări într-un singur volum ale lui; ca, de pildă, lucrarea Despre purtarea de grijă și cartea alcătuită de el Despre iudei și Omul de stat; și mai departe, Alexandru sau Despre stăpânirea rațiunii de către animalele neraționale. Pe lângă acestea este o lucrare Despre propoziția că orice om rău este rob, la care se adaugă lucrarea Despre propoziția că orice om bun este liber."},{"v":7,"t":"După acestea a fost alcătuită de el lucrarea Despre viața contemplativă sau Despre rugători, din care am luat faptele despre viața oamenilor apostolici; și mai departe, Tâlcuirea numelor ebraice din Lege și din Proroci se spune că este rodul sârguinței lui."},{"v":8,"t":"Și se spune că a citit în fața întregului Senat roman în domnia lui Claudiu lucrarea pe care o scrisese, când a venit la Roma sub Caiu, despre ura lui Caiu față de zei și căreia, cu referire ironică la firea ei, îi dăduse titlul Despre virtuți. Și cuvântările lui au fost atât de admirate încât au fost socotite vrednice de un loc în biblioteci."},{"v":9,"t":"În acest timp, pe când Pavel își ducea la capăt călătoria „de la Ierusalim și în jur până în Iliric” (Romani 15:19), Claudiu a izgonit pe iudei din Roma; și Acuila și Priscila, părăsind Roma cu ceilalți iudei, au venit în Asia și au locuit acolo cu apostolul Pavel, care întărea bisericile acelei regiuni ale căror temelii le pusese de curând. Sfânta carte a Faptelor ne înștiințează și despre aceste lucruri."}];
window.LIB_LAZY["eusebiu-istoria#33"]=[{"v":1,"t":"Pe când Claudiu era încă împărat, s-a întâmplat că o atât de mare tulburare și neorânduială a avut loc la Ierusalim, la sărbătoarea Paștilor, încât treizeci de mii dintre iudeii care fuseseră îngrămădiți cu forța la poarta templului au pierit, fiind călcați în picioare unii de alții. Astfel sărbătoarea a devenit un timp de jale pentru tot neamul și a fost plâns în fiecare casă. Aceste lucruri sunt povestite literal de Josephus."},{"v":2,"t":"Dar Claudiu l-a rânduit pe Agrippa, fiul lui Agrippa, rege al iudeilor, trimițând pe Felix ca procurator peste toată țara Samariei și Galileii și peste ținutul numit Perea. Și după ce a domnit treisprezece ani și opt luni, a murit și l-a lăsat pe Nero ca urmaș în imperiu."}];
window.LIB_LAZY["eusebiu-istoria#34"]=[{"v":1,"t":"Josephus povestește iarăși, în cartea a douăzecea a Antichităților sale, cearta care s-a ridicat între preoți în domnia lui Nero, pe când Felix era procurator al Iudeii."},{"v":2,"t":"Cuvintele lui sunt următoarele: S-a ridicat o ceartă între marii preoți, pe de o parte, și preoții și conducătorii poporului din Ierusalim, pe de alta. Și fiecare dintre ei a adunat o ceată dintre cei mai îndrăzneți și mai neliniștiți oameni și s-a pus în fruntea lor și, ori de câte ori se întâlneau, își aruncau unii în alții ocări și pietre. Și nu era nimeni care să se amestece; ci aceste lucruri se făceau după voie, ca într-o cetate lipsită de cârmuitor."},{"v":3,"t":"Și atât de mare era neobrăzarea și îndrăzneala marilor preoți încât au cutezat să-și trimită slujitorii la arii ca să ia zeciuielile datorate preoților; și astfel preoții care erau săraci se vedea că pier de lipsă. În acest chip a stăpânit silnicia facțiunilor peste orice dreptate."},{"v":4,"t":"Și același autor povestește iarăși că pe la același timp s-a ivit în Ierusalim un anume fel de tâlhari, „care ziua”, cum spune el, „și în mijlocul cetății omorau pe cei care le ieșeau în cale”."},{"v":5,"t":"Căci, mai ales la sărbători, se amestecau cu mulțimea și, cu săbii scurte, pe care le ascundeau sub veșminte, înjunghiau pe cei mai de seamă oameni. Și când aceștia cădeau, ucigașii înșiși erau printre cei care își arătau indignarea. Și astfel, din pricina încrederii pe care o aveau toți în ei, au rămas nedescoperiți."},{"v":6,"t":"Cel dintâi omorât de ei a fost Ionatan, marele preot; și după el mulți erau omorâți în fiecare zi, până ce frica a ajuns mai rea decât răul însuși, fiecare, ca în bătălie, așteptând moartea din ceas în ceas."}];
window.LIB_LAZY["eusebiu-istoria#35"]=[{"v":1,"t":"După alte lucruri, merge mai departe astfel: Dar iudeii au fost chinuiți de o ciumă mai mare decât acestea de către proorocul mincinos egiptean. Căci s-a ivit în țară un înșelător care a stârnit încredere în el ca prooroc și a adunat vreo treizeci de mii dintre cei pe care îi amăgise și i-a dus din pustiu la așa-numitul Munte al Măslinilor, de unde era pregătit să intre cu forța în Ierusalim și să biruie garnizoana romană și să pună stăpânire pe cârmuirea poporului, slujindu-se de cei care făceau atacul împreună cu el ca de gardă de corp."},{"v":2,"t":"Dar Felix i-a prevenit atacul și a ieșit în întâmpinarea lui cu legionarii romani și tot poporul s-a unit la apărare, așa că, când s-a dat bătălia, egipteanul a fugit cu câțiva urmași, dar cei mai mulți dintre ei au fost nimiciți sau luați prizonieri."},{"v":3,"t":"Josephus povestește aceste întâmplări în cartea a doua a Istoriei sale. Dar merită să punem alături povestirea despre egiptean dată aici cu cea cuprinsă în Faptele Apostolilor. În vremea lui Felix i s-a spus lui Pavel de către centurionul din Ierusalim, când mulțimea iudeilor a ridicat o tulburare împotriva apostolului: „Nu ești tu cel care mai înainte de aceste zile ai făcut o răscoală și ai scos în pustiu patru mii de oameni care erau ucigași?” (Fapte 21:38) Acestea sunt întâmplările care au avut loc în vremea lui Felix."}];
window.LIB_LAZY["eusebiu-istoria#36"]=[{"v":1,"t":"Fest a fost trimis de Nero să-i fie urmaș lui Felix. Sub el, Pavel, după ce și-a făcut apărarea, a fost trimis în lanțuri la Roma. Cu el era Aristarh, pe care undeva în epistolele lui îl numește, destul de firesc, tovarășul lui de temniță. (Coloseni 4:10) Și Luca, care a scris Faptele Apostolilor, și-a încheiat istoria la acest punct, după ce a spus că Pavel a petrecut doi ani întregi la Roma ca prizonier slobod și a predicat cuvântul lui Dumnezeu fără opreliște."},{"v":2,"t":"Astfel, după ce și-a făcut apărarea, se spune că apostolul a fost trimis din nou la slujba predicării și că, venind a doua oară în aceeași cetate, a suferit martiriul. În această temniță a scris a doua epistolă către Timotei, în care pomenește prima lui apărare și moartea lui apropiată."},{"v":3,"t":"Dar auzi mărturia lui despre aceste lucruri: „La prima mea apărare”, spune el, „nimeni nu a stat cu mine, ci toți m-au părăsit: mă rog lui Dumnezeu să nu li se pună în seamă. Totuși Domnul a stat cu mine și m-a întărit; ca prin mine predicarea să fie pe deplin cunoscută și toate neamurile să audă; și am fost izbăvit din gura leului.” (2 Timotei 4:16-17)"},{"v":4,"t":"Arată limpede prin aceste cuvinte că, cu prilejul de mai înainte, pentru ca predicarea să fie împlinită prin el, a fost scăpat din gura leului, referindu-se, în această expresie, la Nero, după cum este probabil din pricina cruzimii acestuia. De aceea nu a adăugat după aceea o spusă asemănătoare: «Mă va scăpa din gura leului»; căci vedea în duh că sfârșitul lui nu va fi zăbovit mult."},{"v":5,"t":"De aceea adaugă la cuvintele: „Și m-a izbăvit din gura leului” această frază: „Domnul mă va izbăvi de orice lucrare rea și mă va păstra pentru împărăția Sa cerească” (2 Timotei 4:18), arătând martiriul lui grabnic; pe care îl prevestește și mai limpede în aceeași epistolă, când scrie: „Căci eu sunt acum gata să fiu jertfit și vremea despărțirii mele este aproape.”"},{"v":6,"t":"În a doua epistolă către Timotei, mai mult, arată că Luca era cu el când a scris, dar la prima lui apărare nici măcar el nu era. De unde este probabil că Luca a scris Faptele Apostolilor în acel timp, continuându-și istoria până la perioada când a fost cu Pavel."},{"v":7,"t":"Dar aceste lucruri le-am adus noi ca să arătăm că martiriul lui Pavel nu a avut loc în vremea acelei șederi la Roma pe care o însemnează Luca."},{"v":8,"t":"Este probabil, într-adevăr, că, pe măsură ce Nero era mai dispus la blândețe la început, apărarea de către Pavel a învățăturii lui a fost primită mai ușor; dar când a înaintat la săvârșirea unor fapte de îndrăzneală fără lege, i-a făcut pe apostoli, ca și pe alții, ținta atacurilor lui."}];
window.LIB_LAZY["eusebiu-istoria#37"]=[{"v":1,"t":"Dar după ce Pavel, în urma apelului lui la Cezar, a fost trimis la Roma de Fest, iudeii, fiind înșelați în nădejdea lor de a-l prinde în cursele pe care i le puseseră, s-au întors împotriva lui Iacov, fratele Domnului, căruia scaunul de episcop din Ierusalim îi fusese încredințat de apostoli. Următoarele măsuri îndrăznețe au fost întreprinse de ei împotriva lui."},{"v":2,"t":"Ducându-l în mijlocul lor, i-au cerut să se lepede de credința în Hristos în prezența întregului popor. Dar, împotriva părerii tuturor, cu glas limpede și cu mai multă îndrăzneală decât se așteptaseră, a vorbit înaintea întregii mulțimi și a mărturisit că Mântuitorul și Domnul nostru Isus este Fiul lui Dumnezeu. Dar ei nu au mai putut îndura mărturia omului care, din pricina excelenței virtuții ascetice și a evlaviei pe care o arăta în viața lui, era socotit de toți cel mai drept dintre oameni și de aceea l-au omorât. Prilejul pentru această faptă de silnicie a fost dat de anarhia care stăpânea, pricinuită de faptul că Fest murise tocmai atunci în Iudeea și provincia era astfel fără guvernator și căpetenie."},{"v":3,"t":"Chipul morții lui Iacov a fost deja arătat prin cuvintele lui Clement citate mai sus, care însemnează că a fost aruncat de pe acoperișul templului și bătut până la moarte cu o măciucă. Dar Hegesip, care a trăit îndată după apostoli, dă cea mai exactă povestire în cartea a cincea a Memoriilor sale. Scrie astfel:"},{"v":4,"t":"Iacov, fratele Domnului, a urmat la cârmuirea Bisericii împreună cu apostolii. A fost numit Cel Drept de toți din vremea Mântuitorului nostru până în ziua de azi; căci erau mulți care purtau numele de Iacov."},{"v":5,"t":"Era sfânt din pântecele mamei lui; și nu a băut vin, nici băutură tare, și nu a mâncat carne. Nicio custură nu s-a atins de capul lui; nu s-a uns cu untdelemn și nu a folosit baia."},{"v":6,"t":"El singur avea voie să intre în locul sfânt; căci purta veșminte nu de lână, ci de in. Și avea obiceiul să intre singur în templu și era găsit adesea în genunchi, cerând iertare pentru popor, așa încât genunchii lui s-au făcut tari ca ai unei cămile, din pricina îndoirii lor neîncetate în închinarea lui către Dumnezeu și în cererea de iertare pentru popor."},{"v":7,"t":"Din pricina dreptății lui nemăsurate a fost numit Cel Drept și Oblias, care înseamnă în grecește «Întăritura poporului» și «Dreptate», potrivit cu ce declară proorocii despre el."},{"v":8,"t":"Unele dintre cele șapte secte care existau în popor și care au fost pomenite de mine în Memorii l-au întrebat: «Care este poarta lui Isus?» și el a răspuns că El este Mântuitorul."},{"v":9,"t":"Din pricina acestor cuvinte unii au crezut că Isus este Hristosul. Dar sectele pomenite mai sus nu credeau nici în înviere, nici în venirea cuiva ca să dea fiecărui om după faptele lui. Dar câți au crezut, au crezut din pricina lui Iacov."},{"v":10,"t":"De aceea, când au crezut și mulți dintre cârmuitori, s-a făcut o tulburare între iudei și cărturari și farisei, care spuneau că este primejdie ca tot poporul să-L aștepte pe Isus ca pe Hristos. Venind deci laolaltă la Iacov, i-au zis: «Te rugăm, stăpânește poporul; căci s-a rătăcit în privința lui Isus, ca și cum ar fi Hristosul. Te rugăm să-i convingi pe toți care au venit la sărbătoarea Paștilor în privința lui Isus; căci toți avem încredere în tine. Căci îți dăm mărturie, ca și tot poporul, că ești drept și nu ai față de oameni. (Matei 22:16)"},{"v":11,"t":"De aceea, convinge mulțimea să nu se lase rătăcită în privința lui Isus. Căci tot poporul și noi toți avem încredere în tine. Stai deci pe acoperișul templului, ca din acea înălțime să fii văzut limpede și cuvintele tale să poată fi auzite ușor de tot poporul. Căci toate semințiile, cu neamurile de asemenea, s-au adunat din pricina Paștilor.»"},{"v":12,"t":"Cărturarii și fariseii pomeniți l-au așezat deci pe Iacov pe acoperișul templului și au strigat către el și au zis: «Tu, cel drept, în care ar trebui să avem toți încredere, de vreme ce poporul este rătăcit după Isus, cel răstignit, spune-ne care este poarta lui Isus.»"},{"v":13,"t":"Și el a răspuns cu glas tare: «De ce mă întrebați despre Isus, Fiul Omului? El Însuși șade în cer, la dreapta marii Puteri, și este gata să vină pe norii cerului.»"},{"v":14,"t":"Și când mulți erau pe deplin convinși și se măreau cu mărturia lui Iacov și ziceau: «Osana Fiului lui David», acești același cărturari și farisei au zis iarăși unii altora: «Am făcut rău dând o asemenea mărturie lui Isus. Dar să ne ducem și să-l aruncăm jos, ca să se teamă să-l creadă.»"},{"v":15,"t":"Și au strigat, zicând: «O! O! Și cel drept este în rătăcire.» Și au împlinit Scriptura scrisă în Isaia: «Să luăm din calea noastră pe cel drept, pentru că ne este supărător: de aceea își vor mânca rodul faptelor lor.»"},{"v":16,"t":"Astfel s-au urcat și au aruncat jos pe cel drept și și-au zis unii altora: «Să-l ucidem cu pietre pe Iacov cel Drept.» Și au început să-l ucidă cu pietre, căci nu a fost omorât de cădere; ci s-a întors și a îngenuncheat și a zis: «Vă rog, Doamne Dumnezeule, Tatăl nostru, iartă-i, căci nu știu ce fac.» (Luca 23:34)"},{"v":17,"t":"Și pe când îl ucideau astfel cu pietre, unul dintre preoți, dintre fiii lui Recab, fiul recabiților, care sunt pomeniți de proorocul Ieremia, a strigat, zicând: «Opriți-vă. Ce faceți? Cel drept se roagă pentru voi.»"},{"v":18,"t":"Și unul dintre ei, care era pivar, a luat bâta cu care bătea hainele și a lovit pe cel drept peste cap. Și astfel a suferit martiriul. Și l-au îngropat chiar în loc, lângă templu, și monumentul lui rămâne și acum lângă templu. A devenit un martor adevărat, și iudeilor, și grecilor, că Isus este Hristosul. Și îndată Vespasian i-a asediat."},{"v":19,"t":"Aceste lucruri sunt povestite pe larg de Hegesip, care se învoiește cu Clement. Iacov era un om atât de minunat și atât de vestit între toți pentru dreptatea lui încât cei mai cu minte chiar dintre iudei erau de părere că aceasta a fost pricina asediului Ierusalimului, care li s-a întâmplat îndată după martiriul lui, pentru nicio altă pricină decât fapta lor îndrăzneață împotriva lui."},{"v":20,"t":"Josephus, cel puțin, nu a șovăit să mărturisească aceasta în scrierile lui, unde spune: „Aceste lucruri s-au întâmplat iudeilor ca să se răzbune pe Iacov Cel Drept, care era fratele lui Isus, numit Hristosul. Căci iudeii l-au omorât, deși era un om preadrept.”"},{"v":21,"t":"Și același scriitor însemnează și moartea lui în cartea a douăzecea a Antichităților sale, în cuvintele următoare: Dar împăratul, când a aflat de moartea lui Fest, l-a trimis pe Albin să fie procurator al Iudeii. Dar Anan cel tânăr, care, după cum am spus deja, căpătase marea preoție, era de o fire nemăsurat de îndrăzneață și nechibzuită. Aparținea, pe lângă aceasta, sectei saducheilor, care sunt cei mai cruzi dintre toți iudeii în împlinirea judecății, după cum am arătat deja."},{"v":22,"t":"Anan, fiind, deci, de acest fel și socotind că are un prilej favorabil din pricina faptului că Fest murise, iar Albin era încă pe drum, a adunat Sinedriul și a adus înaintea lui pe fratele lui Isus, așa-numitul Hristos, cu numele Iacov, împreună cu alții, și i-a învinuit de încălcarea legii și i-a osândit să fie uciși cu pietre."},{"v":23,"t":"Dar cei din cetate care păreau cei mai cumpătați și pricepuți în lege s-au mâniat tare pe aceasta și au trimis în taină la rege, rugându-l să poruncească lui Anan să înceteze asemenea fapte. Căci nu făcuse bine nici măcar această primă dată. Și unii dintre ei au mers și în întâmpinarea lui Albin, care călătorea de la Alexandria, și i-au amintit că nu era îngăduit lui Anan să cheme Sinedriul fără știrea lui."},{"v":24,"t":"Și Albin, fiind înduplecat de înfățișările lor, a scris cu mânie lui Anan, amenințându-l cu pedeapsă. Și regele Agrippa, în urma aceasta, l-a lipsit de marea preoție, pe care o ținuse trei luni, și a rânduit pe Isus, fiul lui Damneu."},{"v":25,"t":"Aceste lucruri sunt însemnate în privința lui Iacov, despre care se spune că este autorul celei dintâi dintre așa-numitele epistole catolice. Dar trebuie să se țină seama că ea este disputată; cel puțin, nu mulți dintre cei din vechime au pomenit-o, cum este cazul și cu epistola care poartă numele lui Iuda, care este și ea una dintre cele șapte așa-numite epistole catolice. Totuși știm că și acestea, cu restul, au fost citite public în foarte multe biserici."}];
window.LIB_LAZY["eusebiu-istoria#38"]=[{"v":1,"t":"Când Nero era în al optulea an al domniei lui, Anian i-a urmat lui Marcu Evanghelistul în cârmuirea parohiei Alexandriei."}];
window.LIB_LAZY["eusebiu-istoria#39"]=[{"v":1,"t":"Când cârmuirea lui Nero era acum bine întărită, a început să se afunde în îndeletniciri nesfințite și s-a înarmat chiar împotriva religiei Dumnezeului universului."},{"v":2,"t":"A descrie mărimea stricăciunii lui nu intră în planul lucrării de față. Deoarece sunt într-adevăr mulți care i-au însemnat istoria în povestiri foarte exacte, fiecare poate afla după plac din ele grosolănia nebuniei neobișnuite a omului, sub înrâurirea căreia, după ce a săvârșit nimicirea atâtor zeci de mii fără nicio pricină, a căzut într-o asemenea vinovăție de sânge încât nu și-a cruțat nici cele mai apropiate rude și cei mai dragi prieteni, ci a nimicit pe mama lui și pe frații lui și pe nevasta lui, cu foarte mulți alții din propria lui familie, ca pe dușmani privați și publici, cu felurite feluri de moarte."},{"v":3,"t":"Dar cu toate acestea mai lipsea din catalogul crimelor lui această particularitate, că a fost cel dintâi dintre împărați care s-a arătat dușman al religiei dumnezeiești."},{"v":4,"t":"Romanul Tertulian este și el martor al aceasta. Scrie astfel: „Cercetați înscrisurile voastre. Acolo veți găsi că Nero a fost cel dintâi care a prigonit această învățătură, mai ales atunci când, după ce supusese tot răsăritul, și-a exercitat cruzimea împotriva tuturor la Roma. Ne mândrim că avem un asemenea om drept conducător al pedepsirii noastre. Căci oricine îl cunoaște poate înțelege că nimic nu era osândit de Nero decât dacă era ceva de mare excelență.”"},{"v":5,"t":"Vestindu-se astfel pe față ca cel dintâi dintre cei mai de seamă dușmani ai lui Dumnezeu, a fost dus la omorârea apostolilor. Se însemnează, deci, că Pavel a fost decapitat chiar la Roma și că Petru a fost răstignit de asemenea sub Nero. Această povestire despre Petru și Pavel este întărită de faptul că numele lor sunt păstrate în cimitirele acelui loc până în ziua de azi."},{"v":6,"t":"Este confirmată de asemenea de Caiu, un membru al Bisericii, care s-a ridicat sub Zefirin, episcopul Romei. El, într-o disputare publicată cu Proclu, conducătorul ereziei frigiene, vorbește astfel despre locurile unde sunt așezate sfintele trupuri ale apostolilor pomeniți:"},{"v":7,"t":"„Dar eu vă pot arăta trofeele apostolilor. Căci dacă veți merge la Vatican sau pe calea Ostiei, veți găsi trofeele celor care au pus temeliile acestei biserici.”"},{"v":8,"t":"Și că amândoi au suferit martiriul în același timp este spus de Dionisie, episcopul Corintului, în epistola lui către romani, în cuvintele următoare: „Ați legat astfel, printr-un asemenea îndemn, sădirea lui Petru și a lui Pavel la Roma și la Corint. Căci amândoi au sădit și ne-au învățat la fel în Corintul nostru. Și au învățat împreună, în același chip, în Italia și au suferit martiriul în același timp.” Am citat aceste lucruri ca adevărul istoriei să fie și mai întărit."}];
window.LIB_LAZY["eusebiu-istoria#40"]=[{"v":1,"t":"Josephus, iarăși, după ce povestește multe lucruri în legătură cu nenorocirea care a venit peste tot neamul iudeilor, însemnează, pe lângă multe alte împrejurări, că un mare număr dintre cei mai cinstiți dintre iudei au fost biciuiți chiar la Ierusalim și apoi răstigniți de Flor. S-a întâmplat că el era procurator al Iudeii când războiul a început să se aprindă, în al doisprezecelea an al lui Nero."},{"v":2,"t":"Josephus spune că în acel timp o cumplită tulburare s-a stârnit în toată Siria în urma răscoalei iudeilor și că pretutindeni aceștia au fost nimiciți fără milă, ca dușmani, de locuitorii cetăților, „astfel încât puteai vedea cetăți pline de leșuri neîngropate și trupurile moarte ale bătrânilor risipite laolaltă cu trupurile pruncilor și femei fără măcar o acoperire pentru goliciunea lor și toată provincia plină de nenorociri de nespus, în timp ce groaza lucrurilor cu care erau amenințați era mai mare decât suferințele înseși pe care le îndurau oriunde”. Aceasta este povestirea lui Josephus; și aceasta era starea iudeilor în acel timp."}];
